-- =====================================================================
-- 0054 · CATÁLOGO DE OPERACIONES Y SUPUESTOS AUTOCORREGIDOS · v0.40.0
-- ---------------------------------------------------------------------
-- Dos piezas de la ontología (plan de ejecución):
--   · OPERACIONES (erp.operations): las operaciones típicas de una pyme con la pantalla del ERP en que se registran,
--     su asiento modelo, las cuentas que la identifican, su concepto del glosario y sus fuentes oficiales.
--     erp.operation_for_lines(líneas) dice a qué operación se parece un asiento: así el Tutor dice DÓNDE se registra.
--   · CASOS (erp.exercises): supuestos prácticos con su enunciado, el asiento esperado, la explicación, los errores
--     frecuentes y la norma. erp.grade_exercise corrige una respuesta línea a línea (cuenta por su grupo o subgrupo del
--     PGC, lado e importe); erp.submit_exercise la guarda (erp.exercise_attempts) para seguir el progreso de cada
--     usuario y para medir a la IA («Evaluar la IA»: la misma corrección sobre el asiento que propone el Tutor).
-- Base documental (0053): las fuentes de los supuestos (PGC, LIS, LIRPF y su reglamento, LGSS, Orden de cotización).
-- Re-ejecutable. Empieza reponiendo el glosario completo en erp.concepts (por si faltaba algún término).
-- =====================================================================

-- 0) Glosario completo (reparación): las operaciones y los casos apuntan a sus conceptos (clave foránea), así que
--    primero se asegura que erp.concepts tiene TODOS los términos del glosario, por si alguna migración anterior no
--    llegó a insertarlos en esta base de datos. Son las mismas filas (generadas con frontend/tests/glossarySql.js).
insert into erp.concepts (key, sort, term, definition, example, term_en, definition_en, example_en, bc, sap, pgc) values
('debit', 10, 'Debe', 'Lado izquierdo de una cuenta. Aumentan por el Debe lo que tienes (caja, bancos, clientes) y los gastos.', 'Cobras 100 € en el banco: 572 al Debe.', 'Debit', 'Left side of an account. Assets (cash, bank, customers) and expenses increase on the debit side.', 'You collect €100 in the bank: 572 debit.', 'Debit Amount', 'Debit (S)', '{}'),
('credit', 20, 'Haber', 'Lado derecho de una cuenta. Aumentan por el Haber lo que debes (proveedores, préstamos), el capital y los ingresos.', 'Vendes por 100 €: 700 al Haber.', 'Credit', 'Right side of an account. Liabilities (suppliers, loans), equity and income increase on the credit side.', 'You sell for €100: 700 credit.', 'Credit Amount', 'Credit (H)', '{}'),
('doubleEntry', 30, 'Partida doble', 'Todo hecho económico mueve al menos dos cuentas, y la suma del Debe es siempre igual a la del Haber.', null, 'Double entry', 'Every transaction moves at least two accounts, and total debits always equal total credits.', null, 'Double-entry', 'Double-entry', '{}'),
('entry', 40, 'Asiento', 'Anotación de un hecho económico en la contabilidad: una fecha, un concepto y varias líneas (apuntes) que cuadran.', null, 'Journal entry', 'Record of a transaction in the books: a date, a description and several lines that balance.', null, 'G/L Entries (Document)', 'Accounting document (BKPF)', '{}'),
('draft', 50, 'Borrador', 'Asiento guardado pero no contabilizado: se puede cambiar o borrar y no cuenta en los informes.', null, 'Draft', 'An entry saved but not posted: it can be changed or deleted and does not count in the reports.', null, 'General Journal line', 'Parked document', '{}'),
('posting', 60, 'Contabilizar', 'Dar por definitivo un asiento: recibe su número correlativo, entra en los libros y ya no se puede cambiar.', null, 'Post', 'Make an entry final: it gets its sequential number, goes into the books and can no longer be changed.', null, 'Post', 'Post', '{}'),
('reversal', 70, 'Contraasiento', 'Asiento igual que otro pero con el Debe y el Haber cambiados: lo anula sin borrarlo, dejando rastro.', null, 'Reversal entry', 'An entry identical to another with debit and credit swapped: it cancels it without deleting it, leaving a trail.', null, 'Reverse Transaction', 'Reverse document (FB08)', '{}'),
('subaccount', 80, 'Subcuenta', 'Cuenta de último nivel donde se apunta, con todos sus dígitos. Cuelga de una cuenta del PGC.', '57200001 (un banco) cuelga de la 572 (Bancos).', 'Posting account', 'Last-level account where amounts are posted, with all its digits. It belongs to a chart-of-accounts account.', '57200001 (a bank) belongs to 572 (Banks).', 'G/L Account (Posting)', 'G/L account (SKB1)', '{}'),
('chart', 90, 'Plan General Contable (PGC)', 'Norma española (RD 1514/2007) que fija las cuentas, su numeración y cómo se valoran las operaciones.', null, 'Spanish GAAP (PGC)', 'Spanish standard (RD 1514/2007) that sets the accounts, their numbering and how transactions are measured.', null, 'Chart of Accounts', 'Chart of accounts (SKA1)', '{}'),
('partner', 100, 'Tercero', 'Cliente, proveedor, acreedor o deudor. Cada uno tiene su subcuenta (430, 400, 410, 440) y su NIF.', null, 'Business partner', 'Customer, supplier, creditor or debtor. Each has its own account (430, 400, 410, 440) and tax ID.', null, 'Customer / Vendor', 'Business Partner', '{400,410,430,440}'),
('fiscalYear', 110, 'Ejercicio', 'Periodo de 12 meses al que se refieren las cuentas anuales. Se abre, se lleva y se cierra.', null, 'Fiscal year', 'The 12-month period the annual accounts refer to. It is opened, kept and closed.', null, 'Accounting Period (year)', 'Fiscal year', '{}'),
('closing', 120, 'Cierre del ejercicio', 'Regularización (gastos e ingresos a la 129), asiento de cierre (todo a cero) y apertura del ejercicio siguiente.', null, 'Year-end closing', 'Closing the P&L into account 129, the closing entry (all to zero) and the opening entry of the next year.', null, 'Close Income Statement', 'Balance carryforward (FAGLGVTR)', '{129}'),
('journal', 130, 'Libro diario', 'Todos los asientos por orden de fecha y número. Es obligatorio (Código de Comercio, art. 28).', null, 'General journal', 'All entries in date and number order. It is a legal book in Spain.', null, 'G/L Register', 'Journal', '{}'),
('ledger', 140, 'Libro mayor', 'Los movimientos de una sola cuenta con su saldo acumulado.', null, 'General ledger', 'The movements of a single account with its running balance.', null, 'G/L Account Statement', 'Line items (FBL3N)', '{}'),
('trialBalance', 150, 'Balance de sumas y saldos', 'Por cada cuenta, la suma del Debe, la del Haber y su saldo. Si la contabilidad cuadra, los totales coinciden.', null, 'Trial balance', 'For each account, total debits, total credits and the balance. If the books balance, the totals match.', null, 'Trial Balance', 'Balance list (S_ALR_87012277)', '{}'),
('inverseBalance', 160, 'Saldo anómalo', 'Saldo contrario a la naturaleza de la cuenta: una caja acreedora o un cliente con saldo acreedor. Suele ser un error o una reclasificación pendiente.', null, 'Inverse balance', 'A balance against the nature of the account: cash in credit or a customer in credit. Usually an error or a pending reclassification.', null, '—', '—', '{}'),
('balance', 170, 'Balance de situación', 'Foto del patrimonio en una fecha: lo que la empresa tiene (activo) y cómo se financia (patrimonio neto y pasivo).', null, 'Balance sheet', 'A snapshot at a date: what the company owns (assets) and how it is financed (equity and liabilities).', null, 'Balance Sheet', 'Balance sheet', '{}'),
('pyg', 180, 'Cuenta de pérdidas y ganancias', 'Ingresos menos gastos de un periodo: el resultado (beneficio o pérdida).', null, 'Income statement', 'Income minus expenses for a period: the result (profit or loss).', null, 'Income Statement', 'P&L statement', '{}'),
('equity', 190, 'Patrimonio neto', 'Lo que es de los socios: capital, reservas y resultados. Activo menos pasivo.', null, 'Equity', 'What belongs to the owners: capital, reserves and results. Assets minus liabilities.', null, 'Equity', 'Equity', '{10,11,12}'),
('cashflow', 200, 'Estado de flujos de efectivo (EFE)', 'De dónde viene y a dónde va la caja: actividades de explotación, inversión y financiación.', 'Método directo (cobros y pagos) o indirecto (desde el resultado).', 'Cash flow statement', 'Where cash comes from and where it goes: operating, investing and financing activities.', 'Direct method (receipts and payments) or indirect (from the result).', 'Cash Flow Statement', 'Cash flow statement', '{}'),
('ratio', 210, 'Ratio', 'Cociente entre dos partidas que resume la salud de la empresa: liquidez, endeudamiento, rentabilidad.', 'Liquidez = activo corriente / pasivo corriente.', 'Ratio', 'A quotient of two items that summarises the company’s health: liquidity, leverage, profitability.', 'Current ratio = current assets / current liabilities.', 'KPI / Analysis View', 'KPI', '{}'),
('workingCapital', 220, 'Fondo de maniobra', 'Activo corriente menos pasivo corriente: el colchón para pagar las deudas a corto plazo.', null, 'Working capital', 'Current assets minus current liabilities: the cushion to pay short-term debts.', null, 'Working Capital', 'Working capital', '{}'),
('depreciation', 230, 'Amortización', 'Reparto del coste de un inmovilizado a lo largo de su vida útil: gasto (68x) contra amortización acumulada (28x).', null, 'Depreciation', 'Spreading a fixed asset’s cost over its useful life: expense (68x) against accumulated depreciation (28x).', null, 'Depreciation', 'Depreciation (AFAB)', '{28,68}'),
('vat', 240, 'IVA', 'Impuesto sobre el Valor Añadido, en la Península y Baleares. La empresa lo cobra en sus ventas y lo paga en sus compras; ingresa la diferencia.', 'Tipos: 21 %, 10 %, 4 %.', 'VAT (IVA)', 'Value Added Tax, in mainland Spain and the Balearics. The company charges it on sales and pays it on purchases, paying over the difference.', 'Rates: 21%, 10%, 4%.', 'VAT', 'Tax code (MWSKZ)', '{472,477}'),
('igic', 250, 'IGIC', 'Impuesto General Indirecto Canario: el equivalente del IVA en Canarias, con tipos propios.', 'Tipo general 7 %; se declara en el modelo 420.', 'IGIC', 'Canary Islands General Indirect Tax: the Canary Islands’ equivalent of VAT, with its own rates.', 'Standard rate 7%; filed on form 420.', 'VAT (local)', 'Tax code', '{472,477}'),
('inputTax', 260, 'IVA / IGIC soportado (472)', 'El impuesto que te cobran tus proveedores. Es un derecho frente a Hacienda: se resta en la liquidación.', null, 'Input VAT / IGIC (472)', 'The tax your suppliers charge you. It is a claim on the tax office: it is deducted in the settlement.', null, 'Purchase VAT', 'Input tax', '{472}'),
('outputTax', 270, 'IVA / IGIC repercutido (477)', 'El impuesto que cobras a tus clientes. Es una deuda con Hacienda hasta que lo liquidas.', null, 'Output VAT / IGIC (477)', 'The tax you charge your customers. It is a debt to the tax office until you settle it.', null, 'Sales VAT', 'Output tax', '{477}'),
('taxBase', 280, 'Base imponible', 'Importe sobre el que se calcula el impuesto: el precio sin IVA ni IGIC.', 'Base 1.000 € × 21 % = 210 € de IVA.', 'Tax base', 'The amount the tax is calculated on: the price before VAT or IGIC.', 'Base €1,000 × 21% = €210 VAT.', 'VAT Base', 'Tax base', '{}'),
('invoice', 290, 'Factura', 'Documento de una compra o venta con sus bases, tipos y cuotas. Al registrarla, el ERP genera el asiento y el libro registro.', null, 'Invoice', 'Document of a purchase or sale with its bases, rates and taxes. When registered, the ERP creates the entry and the tax register line.', null, 'Posted Purchase / Sales Invoice', 'FB60 / FB70', '{}'),
('creditMemo', 300, 'Factura rectificativa', 'Factura que corrige otra (devolución, descuento, error). Nunca se modifica la original.', null, 'Credit memo', 'An invoice that corrects another (return, discount, error). The original is never changed.', null, 'Credit Memo', 'Credit memo', '{}'),
('settlement', 310, 'Liquidación de IVA / IGIC', 'Cada trimestre: repercutido menos soportado. Si sale positivo se paga; si es negativo, se compensa o se pide la devolución en el 4T.', 'Modelos 303 (IVA) y 420 (IGIC).', 'VAT / IGIC settlement', 'Every quarter: output minus input tax. If positive it is paid; if negative it is carried forward or refunded in Q4.', 'Forms 303 (VAT) and 420 (IGIC).', 'Calc. and Post VAT Settlement', 'RFUMSV00', '{4700,4750}'),
('prorata', 320, 'Prorrata', 'Porcentaje del IVA soportado que se puede deducir cuando la empresa hace a la vez operaciones con y sin derecho a deducción.', null, 'Pro rata', 'The share of input VAT that can be deducted when the company has both taxable and exempt sales.', null, 'VAT % Non-deductible', 'Non-deductible input tax', '{472,634,639}'),
('reverseCharge', 330, 'Inversión del sujeto pasivo (ISP)', 'El comprador, no el vendedor, se repercute y se soporta el impuesto a la vez (autorrepercusión).', 'Compras intracomunitarias, obras con subcontratas.', 'Reverse charge', 'The buyer, not the seller, accounts for the tax, charging and deducting it at the same time.', 'Intra-EU purchases, subcontracted construction.', 'Reverse Charge VAT', 'Reverse charge', '{472,477}'),
('surcharge', 340, 'Recargo de equivalencia', 'Régimen de los minoristas personas físicas: su proveedor les cobra un recargo extra y ellos no presentan liquidación de IVA.', null, 'Equivalence surcharge', 'Regime for sole-trader retailers: their supplier charges an extra surcharge and they do not file VAT returns.', null, 'Equivalence surcharge', '—', '{477}'),
('withholding', 350, 'Retención de IRPF', 'Parte de la factura de un profesional o de un alquiler que el pagador ingresa en Hacienda por cuenta del perceptor (4751).', 'Modelos 111 (profesionales) y 115 (alquileres).', 'Income tax withholding', 'Part of a professional’s or landlord’s invoice that the payer pays to the tax office on their behalf (4751).', 'Forms 111 (professionals) and 115 (rents).', 'IRPF withholding', 'Withholding tax', '{4751,473}'),
('openItem', 360, 'Partida abierta', 'Factura que aún no está pagada o cobrada del todo. Un pago se aplica contra ella (la «liquida») y el resto queda pendiente.', 'Factura de 1.060 € con un pago de 500 €: quedan 560 € pendientes.', 'Open item', 'An invoice not yet fully paid or collected. A payment is applied to it and the rest stays open.', 'Invoice of €1,060 with a €500 payment: €560 stays open.', 'Open Vendor / Customer Ledger Entries', 'Open items (FBL1N / FBL5N)', '{400,410,430,440}'),
('aging', 370, 'Antigüedad de saldos', 'Lo pendiente de cada tercero repartido por días de vencido: sin vencer, 1–30, 31–60, 61–90 y más de 90.', 'Más de 90 días vencida: riesgo de impago y posible deterioro (490 / 694).', 'Aging', 'What each partner owes, split by days overdue: not due, 1–30, 31–60, 61–90 and over 90.', 'Over 90 days overdue: risk of non-payment and possible impairment (490 / 694).', 'Aged Accounts Payable / Receivable', 'Due date analysis (S_ALR_87012078)', '{400,410,430,440}'),
('controlledAccount', 380, 'Cuenta controlada', 'Cuenta que solo mueve su módulo (facturas, pagos, liquidación), no un asiento manual. Así la contabilidad y los documentos siempre cuadran.', 'La 410 la abona la factura recibida y la carga su pago.', 'Controlled account', 'An account posted only by its module (invoices, payments, settlement), not by a manual entry. That way the books and the documents always match.', 'Account 410 is credited by the received invoice and debited by its payment.', 'Direct Posting = No', 'Reconciliation account', '{400,410,430,440,472,477}'),
('controlMode', 390, 'Modo estricto o guiado', 'Estricto (como SAP o Business Central): un asiento manual sobre una cuenta controlada no se contabiliza. Guiado (como los ERP españoles): se contabiliza, avisa y queda en Comprobaciones.', null, 'Strict or guided mode', 'Strict (like SAP or Business Central): a manual entry on a controlled account is not posted. Guided (like Spanish ERPs): it is posted, with a warning, and listed in Checks.', null, 'Direct Posting', 'Reconciliation account', '{}'),
('auditCheck', 400, 'Comprobación (control posterior)', 'Cuadre que hace un auditor después de contabilizar: el IVA de la contabilidad frente al libro registro, cada tercero frente a sus facturas, los saldos al revés…', 'La 472 dice 231 € y el libro registro 210 €: sobra un asiento manual de 21 €.', 'Check (detective control)', 'A reconciliation an auditor makes after posting: VAT in the books against the VAT register, each partner against its invoices, balances on the wrong side…', 'Account 472 shows €231 and the VAT register €210: there is a €21 manual entry too many.', 'Reconciliation reports', 'Reconciliation reports', '{}'),
('fixedAsset', 410, 'Inmovilizado', 'Bienes y derechos que la empresa usa en su actividad durante más de un año (local, maquinaria, vehículos, ordenadores, programas). Se registran por su coste y pierden valor con la amortización.', 'Un ordenador de 1.200 € es inmovilizado (217); el papel de la impresora es gasto (629).', 'Fixed asset', 'Goods and rights the company uses in its business for more than a year (premises, machinery, vehicles, computers, software). They are recorded at cost and lose value through depreciation.', 'A €1,200 computer is a fixed asset (217); printer paper is an expense (629).', 'Fixed Asset Card', 'Asset master record (AS01)', '{20,21,22}'),
('netBookValue', 420, 'Valor neto contable', 'Coste del activo menos su amortización acumulada (y su deterioro): lo que vale en el balance. Al venderlo, la diferencia con el precio es el beneficio (77x) o la pérdida (67x).', 'Furgoneta de 18.000 con 2.588,89 amortizados: valor neto 15.411,11; vendida por 14.000 → pérdida de 1.411,11 (671).', 'Net book value', 'Asset cost minus accumulated depreciation (and impairment): what it is worth in the balance sheet. When sold, the difference with the price is the gain (77x) or loss (67x).', 'Van of 18,000 with 2,588.89 depreciated: net value 15,411.11; sold for 14,000 → loss of 1,411.11 (671).', 'Book Value', 'Net book value', '{28}'),
('deferral', 430, 'Periodificación', 'Ajuste de cierre que lleva cada gasto e ingreso al ejercicio al que corresponde (devengo): lo pagado o cobrado por adelantado va a la 480 / 485, y lo devengado sin factura a la 4009 / 4309. Se revierte el primer día del ejercicio siguiente.', 'Seguro anual de 1.200 pagado el 01/10: al 31/12, 900 son del año siguiente → 480 D 900 / 625 H 900; el 01/01, al revés.', 'Accrual adjustment (deferral)', 'A year-end adjustment that moves each expense and income to the year it belongs to (accrual principle): what was paid or collected in advance goes to 480 / 485, and what accrued without an invoice to 4009 / 4309. It is reversed on the first day of the next year.', 'Annual insurance of 1,200 paid on 1 October: at 31 December, 900 belongs to next year → 480 Dr 900 / 625 Cr 900; on 1 January, the other way round.', 'Deferral template', 'Accrual engine (ACE) / deferrals', '{480,485,4009,4309}'),
('badDebt', 440, 'Deterioro de clientes', 'Pérdida estimada por clientes que probablemente no pagarán (NRV 9.ª): 694 al Debe y 490 al Haber, sin tocar la 430. Si pagan, se revierte (794); si la insolvencia es firme, la deuda va a la 650. Fiscalmente, deducible a los 6 meses del vencimiento (art. 13.1 LIS).', 'Factura de 2.420 vencida hace 9 meses: deterioro 694 D 2.420 / 490 H 2.420.', 'Bad debt allowance', 'Estimated loss on customers that will probably not pay (PGC rule 9): 694 debit and 490 credit, without touching 430. If they pay, it is reversed (794); if the loss is definitive, the debt goes to 650. For tax purposes, deductible 6 months after the due date (art. 13.1 LIS).', 'Invoice of 2,420 overdue for 9 months: allowance 694 Dr 2,420 / 490 Cr 2,420.', 'Allowance for doubtful accounts', 'Individual / flat-rate value adjustment', '{490,694,794,650}'),
('provision', 450, 'Provisión', 'Obligación que ya existe por un suceso pasado, cuyo importe o fecha son inciertos (NRV 15.ª): un litigio, un acta, las garantías de lo vendido. Se dota por la mejor estimación, se revisa en cada cierre (más gasto o exceso a la 795) y se aplica al pagar.', 'Demanda probable de 12.000: 678 D 12.000 / 142 H 12.000; si la sentencia es de 14.000 sobre 15.000 provisionados, 1.000 de exceso (7953).', 'Provision', 'An existing obligation from a past event with an uncertain amount or date (PGC rule 15): a lawsuit, a tax assessment, warranties. It is recorded at the best estimate, reviewed at each year end (more expense or excess to 795) and applied when paid.', 'Probable lawsuit of 12,000: 678 Dr 12,000 / 142 Cr 12,000; if the ruling is 14,000 on 15,000 provided, 1,000 excess (7953).', 'Provision (G/L)', 'Provisions (accrual engine)', '{141,142,499,529}'),
('assetImpairment', 460, 'Deterioro del inmovilizado', 'Pérdida de valor de un activo por encima de su amortización: si el valor recuperable es menor que el valor neto contable, la diferencia va a la 69x / 29x (NRV 2.ª). Si se recupera, se revierte (79x) como mucho hasta el valor que tendría sin deterioro.', 'Máquina con valor neto 48.000 y recuperable 40.000: 691 D 8.000 / 2913 H 8.000; desde entonces se amortiza sobre 40.000.', 'Fixed asset impairment', 'A loss of value beyond depreciation: if the recoverable value is below the net book value, the difference goes to 69x / 29x (PGC rule 2). If it recovers, it is reversed (79x) at most up to the value it would have had without the impairment.', 'Machine with a net value of 48,000 and recoverable 40,000: 691 Dr 8,000 / 2913 Cr 8,000; it is then depreciated on 40,000.', 'Write-down', 'Unplanned depreciation', '{290,291,292,690,691,790,791}'),
('inventoryChange', 470, 'Variación de existencias', 'Ajuste del cierre con el método de inventario: se da de baja la existencia inicial y de alta la final del recuento contra la 61x (aprovisionamientos) o la 71x (productos). Así el gasto del año es lo consumido, no lo comprado.', 'Inicial 8.000 + compras 40.000 − final 6.000 = consumo 42.000 (600 40.000 + 610 2.000).', 'Change in inventories', 'A year-end adjustment with the periodic method: the opening stock is removed and the closing count added against 61x (supplies) or 71x (products). So the expense of the year is what was used, not what was bought.', 'Opening 8,000 + purchases 40,000 − closing 6,000 = cost of sales 42,000 (600 40,000 + 610 2,000).', 'Physical inventory', 'Physical inventory / stock change', '{30,31,32,35,39,610,611,612,71}'),
('accrual', 480, 'Devengo', 'Los ingresos y gastos se anotan cuando ocurren, no cuando se cobran o se pagan.', null, 'Accrual', 'Income and expenses are recorded when they occur, not when they are collected or paid.', null, 'Accrual', 'Accrual', '{}'),
('payroll', 490, 'Nómina', 'Recibo mensual del salario. Su asiento lleva el sueldo bruto al gasto (640) y reparte lo que no cobra el trabajador: su cuota de la Seguridad Social (476), la retención de IRPF (4751) y el líquido que se le debe (465), que se paga después.', 'Salario de 2.000 con cuota del trabajador de 151,67 e IRPF del 12 %: 640 D 2.000 / 476 H 151,67 · 4751 H 240 · 465 H 1.608,33.', 'Payslip (payroll)', 'The monthly salary statement. Its entry takes the gross salary to expense (640) and splits what the employee does not receive: their Social Security contribution (476), the IRPF withholding (4751) and the net pay owed (465), paid afterwards.', 'Salary of 2,000 with an employee contribution of 151.67 and 12 % IRPF: 640 Dr 2,000 / 476 Cr 151.67 · 4751 Cr 240 · 465 Cr 1,608.33.', 'Payroll (G/L integration)', 'Payroll posting (HCM)', '{640,642,465,476,4751}'),
('socialSecurity', 500, 'Seguridad Social a cargo de la empresa', 'Lo que la empresa cotiza por cada trabajador además de su sueldo: un % de la base de cotización (salario + prorrata de las pagas extra, con un tope) por contingencias comunes, desempleo, FOGASA, formación, MEI y accidentes de trabajo. Es gasto (642) y se debe a la Seguridad Social (476) hasta que se paga, el mes siguiente.', 'Base 2.333,33 × 31,65 % ≈ 738,50: 642 D 738,50 / 476 H 738,50 (junto con la cuota del trabajador).', 'Employer Social Security', 'What the company contributes for each employee on top of the salary: a % of the contribution base (salary + prorated extra payments, capped) for common contingencies, unemployment, FOGASA, training, MEI and work accidents. It is an expense (642) owed to Social Security (476) until paid, the following month.', 'Base 2,333.33 × 31.65 % ≈ 738.50: 642 Dr 738.50 / 476 Cr 738.50 (together with the employee contribution).', 'Social security (employer contribution)', 'Employer social insurance contribution', '{642,476}'),
('taxForm', 510, 'Modelo tributario (casillas)', 'Impreso oficial con el que se declara un impuesto. Cada importe va en una casilla numerada: en el 303 del IVA, el devengado (01-27), el deducible (28-45) y el resultado (46-71). El ERP lo calcula desde el libro registro y debe coincidir con la liquidación contabilizada.', 'Ventas al 21 % de 11.000: casilla 07 base 11.000, 08 tipo 21, 09 cuota 2.310.', 'Tax form (boxes)', 'The official form used to declare a tax. Each amount goes in a numbered box: in VAT form 303, output tax (01-27), deductible tax (28-45) and the result (46-71). The ERP calculates it from the invoice register and it must match the posted settlement.', 'Sales at 21 % of 11,000: box 07 base 11,000, 08 rate 21, 09 tax 2,310.', 'VAT statement', 'Advance return for tax on sales/purchases', '{472,477,4700,4750}'),
('thirdPartyReturn', 520, 'Modelo 347 (operaciones con terceros)', 'Declaración anual de los clientes y proveedores con los que se han superado 3.005,06 € en el año, IVA incluido, por trimestres. Hacienda la cruza con el 347 del otro: si no coinciden, pide explicaciones. No incluye lo que ya va en otros modelos (349, retenciones).', 'Cliente con 2.420 en el 1T y 1.210 en el 3T: total 3.630 > 3.005,06 → se declara con la clave B.', 'Form 347 (third-party operations)', 'Annual return listing customers and suppliers with more than €3,005.06 in the year, VAT included, by quarter. The tax agency cross-checks it with the other party''s 347. It excludes what other returns already cover (349, withholdings).', 'Customer with 2,420 in Q1 and 1,210 in Q3: total 3,630 > 3,005.06 → declared with key B.', 'Third-party annual return (form 347)', 'Annual return of transactions with third parties', '{400,410,430,440}')
on conflict (key) do update set
  sort = excluded.sort, term = excluded.term, definition = excluded.definition, example = excluded.example,
  term_en = excluded.term_en, definition_en = excluded.definition_en, example_en = excluded.example_en,
  bc = excluded.bc, sap = excluded.sap, pgc = excluded.pgc;

-- 1) Fuentes nuevas (generadas desde frontend/src/sources.js con frontend/tests/sourcesSql.js)
insert into erp.sources (key, issuer, url, checked, title, ref, title_en, ref_en) values
('pgc', 'BOE', 'https://www.boe.es/eli/es/rd/2007/11/16/1514/con', '2026-10-19', 'Real Decreto 1514/2007, Plan General de Contabilidad', 'Marco conceptual (devengo), normas de registro y valoración y cuadro de cuentas', 'Royal Decree 1514/2007, Spanish chart of accounts (PGC)', 'Conceptual framework (accrual), recognition and measurement rules and chart of accounts'),
('lis', 'BOE', 'https://www.boe.es/eli/es/l/2014/11/27/27/con', '2026-10-19', 'Ley 27/2014, del Impuesto sobre Sociedades', 'Arts. 12 (amortizaciones) y 13 (deterioros y provisiones)', 'Law 27/2014 on Corporate Income Tax', 'Arts. 12 (depreciation) and 13 (impairments and provisions)'),
('lirpf', 'BOE', 'https://www.boe.es/eli/es/l/2006/11/28/35/con', '2026-10-19', 'Ley 35/2006, del Impuesto sobre la Renta de las Personas Físicas', 'Arts. 99 a 101: retenciones e ingresos a cuenta', 'Law 35/2006 on Personal Income Tax', 'Arts. 99 to 101: withholdings and payments on account'),
('rirpf', 'BOE', 'https://www.boe.es/eli/es/rd/2007/03/30/439/con', '2026-10-19', 'Real Decreto 439/2007, Reglamento del IRPF', 'Arts. 80 a 101: retenciones del trabajo (art. 82) y de profesionales (art. 95, 15 %)', 'Royal Decree 439/2007, Personal Income Tax Regulation', 'Arts. 80 to 101: payroll (art. 82) and professional (art. 95, 15 %) withholdings'),
('lgss', 'BOE', 'https://www.boe.es/eli/es/rdlg/2015/10/30/8/con', '2026-10-19', 'Real Decreto Legislativo 8/2015, Ley General de la Seguridad Social', 'Art. 147: base de cotización (con la prorrata de las pagas extra)', 'Royal Legislative Decree 8/2015, General Social Security Law', 'Art. 147: contribution base (with prorated extra payments)'),
('cotizacion2026', 'BOE', 'https://www.boe.es/diario_boe/txt.php?id=BOE-A-2026-7296', '2026-10-18', 'Orden PJC/297/2026, de cotización a la Seguridad Social para 2026', 'Tipos de cotización, base máxima (5.101,20 €) y cotización de solidaridad', 'Order PJC/297/2026 on Social Security contributions for 2026', 'Contribution rates, maximum base (€5,101.20) and solidarity contribution')
on conflict (key) do update set issuer = excluded.issuer, url = excluded.url, checked = excluded.checked, title = excluded.title,
  ref = excluded.ref, title_en = excluded.title_en, ref_en = excluded.ref_en;

-- 2) Catálogo de operaciones
create table if not exists erp.operations (
  key            text primary key,
  sort           int not null,
  title          text not null,
  title_en       text not null,
  screen         text not null,          -- pantalla de la empresa donde se registra
  entry          text not null,          -- asiento modelo
  entry_en       text not null,
  accounts       text[] not null,        -- grupos / subgrupos del PGC que la identifican (todos deben estar en el asiento)
  concept        text references erp.concepts(key),
  sources        text[] not null default '{}',
  description    text not null,
  description_en text not null
);
comment on table erp.operations is 'Catalogue of typical operations: where each one is registered in the ERP and its model entry.';
insert into erp.operations (key, sort, title, title_en, screen, entry, entry_en, accounts, concept, sources, description, description_en) values
('purchase_invoice', 10, 'Factura recibida de un proveedor', 'Supplier invoice', 'invoices', '600 / 62x D · 472 D / 400 · 410 H', '600 / 62x Dr · 472 Dr / 400 · 410 Cr', '{600,472,400}', 'invoice', '{liva,pgc}', 'Compras de mercaderías y gastos con su IVA / IGIC soportado. Se registra en Facturas (recibidas): el ERP calcula la cuota y hace el asiento.', 'Purchases and expenses with input VAT / IGIC. Registered in Invoices (received): the ERP calculates the tax and posts the entry.'),
('professional_invoice', 20, 'Factura de un profesional con retención de IRPF', 'Professional invoice with IRPF withholding', 'invoices', '623 D · 472 D / 4751 H · 410 H', '623 Dr · 472 Dr / 4751 Cr · 410 Cr', '{623,4751}', 'withholding', '{lirpf,rirpf}', 'La empresa retiene el IRPF del profesional (15 %) y lo ingresa con el modelo 111. Se registra en Facturas, eligiendo la retención.', 'The company withholds the professionals IRPF (15 %) and pays it with form 111. Registered in Invoices, choosing the withholding.'),
('sale_invoice', 30, 'Factura emitida a un cliente', 'Customer invoice', 'invoices', '430 D / 700 H · 477 H', '430 Dr / 700 Cr · 477 Cr', '{430,700,477}', 'invoice', '{liva,pgc}', 'Ventas con su IVA / IGIC repercutido. Se registra en Facturas (emitidas).', 'Sales with output VAT / IGIC. Registered in Invoices (issued).'),
('credit_memo', 40, 'Factura rectificativa (devolución o descuento)', 'Credit memo (return or discount)', 'invoices', '708 D · 477 D / 430 H', '708 Dr · 477 Dr / 430 Cr', '{708}', 'creditMemo', '{liva,pgc}', 'Corrige una factura ya emitida: reduce la venta y su impuesto. Se registra en Facturas como rectificativa de la original.', 'Corrects an issued invoice: reduces the sale and its tax. Registered in Invoices as a credit memo of the original.'),
('intra_eu_acquisition', 50, 'Adquisición intracomunitaria de bienes', 'Intra-EU acquisition of goods', 'invoices', '600 D · 472 D / 477 H · 400 H', '600 Dr · 472 Dr / 477 Cr · 400 Cr', '{600,472,477,400}', 'reverseCharge', '{liva}', 'El comprador español declara el IVA de la compra a un proveedor de otro país de la UE (autorrepercusión) y a la vez lo deduce. Se registra en Facturas con el tipo «adquisición intracomunitaria».', 'The Spanish buyer self-assesses the VAT on a purchase from another EU country and deducts it at the same time. Registered in Invoices with the intra-EU acquisition rate.'),
('asset_purchase', 60, 'Compra de inmovilizado', 'Fixed asset purchase', 'assets', '21x D · 472 D / 523 · 400 H', '21x Dr · 472 Dr / 523 · 400 Cr', '{21,472}', 'fixedAsset', '{pgc,liva}', 'Se registra la factura en Facturas (a la cuenta 21x) y desde ella se da de alta la ficha en Inmovilizado, que calcula la amortización.', 'Register the invoice in Invoices (account 21x) and create the asset record from it in Fixed assets, which calculates depreciation.'),
('collection', 70, 'Cobro de un cliente', 'Customer collection', 'payments', '572 D / 430 H', '572 Dr / 430 Cr', '{572,430}', 'openItem', '{pgc}', 'Se registra en Cobros y pagos contra la factura: así la factura sabe lo que queda pendiente.', 'Registered in Payments against the invoice, so the invoice knows what is still pending.'),
('payment', 80, 'Pago a un proveedor o acreedor', 'Supplier payment', 'payments', '400 · 410 D / 572 H', '400 · 410 Dr / 572 Cr', '{40,572}', 'openItem', '{pgc}', 'Se registra en Cobros y pagos contra la factura.', 'Registered in Payments against the invoice.'),
('depreciation', 90, 'Amortización del inmovilizado', 'Depreciation', 'assets', '68x D / 28x H', '68x Dr / 28x Cr', '{68,28}', 'depreciation', '{pgc,lis}', 'La calcula Inmovilizado desde la ficha de cada activo, por meses, hasta la fecha que elijas.', 'Fixed assets calculates it from each asset record, by month, up to the date you choose.'),
('accrual', 100, 'Periodificación de gastos o ingresos', 'Accrual or deferral', 'adjustments', '480 D / 6xx H · 7xx D / 485 H', '480 Dr / 6xx Cr · 7xx Dr / 485 Cr', '{48}', 'deferral', '{pgc}', 'Lleva al año siguiente la parte de un gasto o ingreso que le corresponde (principio de devengo). Se registra en Ajustes de cierre y se revierte sola.', 'Moves to next year the part of an expense or income that belongs to it (accrual principle). Registered in Year-end adjustments and reversed automatically.'),
('bad_debt', 110, 'Deterioro de un cliente', 'Bad debt allowance', 'adjustments', '694 D / 490 H', '694 Dr / 490 Cr', '{694,490}', 'badDebt', '{pgc,lis}', 'Se registra en Ajustes de cierre, sobre la factura pendiente; el ERP avisa de si es deducible (art. 13.1 LIS).', 'Registered in Year-end adjustments on the pending invoice; the ERP warns whether it is deductible (art. 13.1 LIS).'),
('provision', 120, 'Provisión', 'Provision', 'adjustments', '6xx D / 14x H', '6xx Dr / 14x Cr', '{14}', 'provision', '{pgc,lis}', 'Obligaciones de importe o fecha inciertos (un litigio, un acta). Se registra en Ajustes de cierre, con su ficha.', 'Obligations with an uncertain amount or date (a lawsuit, a tax assessment). Registered in Year-end adjustments, with its record.'),
('inventory', 130, 'Variación de existencias', 'Inventory change', 'adjustments', '610 D / 30x H · 30x D / 610 H', '610 Dr / 30x Cr · 30x Dr / 610 Cr', '{61,30}', 'inventoryChange', '{pgc}', 'Al cierre, baja de la existencia inicial y alta de la final. Se registra en Ajustes de cierre con el recuento.', 'At year end, remove the opening stock and record the closing stock. Registered in Year-end adjustments with the count.'),
('payroll', 140, 'Nómina', 'Payroll', 'payroll', '640 D · 642 D / 476 H · 4751 H · 465 H', '640 Dr · 642 Dr / 476 Cr · 4751 Cr · 465 Cr', '{640,642}', 'payroll', '{lgss,cotizacion2026,rirpf}', 'Se registra en Nóminas: el ERP calcula el recibo (cuotas e IRPF), hace el asiento y después los pagos.', 'Registered in Payroll: the ERP calculates the payslip (contributions and IRPF), posts the entry and then the payments.'),
('tax_settlement', 150, 'Liquidación del IVA / IGIC', 'VAT / IGIC settlement', 'settlement', '477 D / 472 H · 4750 H', '477 Dr / 472 Cr · 4750 Cr', '{477,472,4750}', 'settlement', '{aeat303,atc420}', 'Al final del trimestre se compensa el repercutido con el soportado. Se registra en Liquidar; el borrador del modelo está en Modelos.', 'At quarter end output tax is offset against input tax. Registered in Settle; the form draft is in Tax forms.'),
('year_closing', 160, 'Regularización y cierre del ejercicio', 'Year-end closing', 'closing', '7xx D / 6xx H · 129 H (o D)', '7xx Dr / 6xx Cr · 129 Cr (or Dr)', '{129}', 'closing', '{pgc}', 'Se registra en Cierre del ejercicio: regularización (6 y 7 contra la 129), cierre y apertura del año siguiente.', 'Registered in Year-end closing: closing of groups 6 and 7 to 129, closing entry and next years opening.'),
('manual_entry', 170, 'Asiento manual (préstamos, gastos bancarios…)', 'Manual entry (loans, bank charges…)', 'entry', '572 D / 170 H · 626 D / 572 H…', '572 Dr / 170 Cr · 626 Dr / 572 Cr…', '{17}', 'entry', '{pgc}', 'Lo que no tiene módulo se registra como asiento manual, con el Tutor de asientos si hace falta.', 'What has no module is registered as a manual entry, with the Entry tutor if needed.')
on conflict (key) do update set sort = excluded.sort, title = excluded.title, title_en = excluded.title_en, screen = excluded.screen,
  entry = excluded.entry, entry_en = excluded.entry_en, accounts = excluded.accounts, concept = excluded.concept,
  sources = excluded.sources, description = excluded.description, description_en = excluded.description_en;

-- 3) Supuestos prácticos
create table if not exists erp.exercises (
  key           text primary key,
  sort          int not null,
  level         text not null check (level in ('basic', 'medium', 'advanced')),
  operation     text not null references erp.operations(key),
  tax_type      text check (tax_type in ('VAT', 'IGIC')),   -- con qué impuesto (null: no depende)
  title         text not null,
  title_en      text not null,
  statement     text not null,
  statement_en  text not null,
  expected      jsonb not null,   -- [{ account (grupo o subgrupo del PGC), side, amount, alt: [cuentas que también valen] }]
  explanation   text not null,
  explanation_en text not null,
  errors        jsonb not null default '[]',   -- errores frecuentes: [{ account, side, msg, msg_en }]
  sources       text[] not null default '{}',
  concept       text references erp.concepts(key)
);
comment on table erp.exercises is 'Practice cases: statement, expected entry, explanation, frequent errors and legal sources.';
insert into erp.exercises (key, sort, level, operation, tax_type, title, title_en, statement, statement_en, expected, explanation, explanation_en, errors, sources, concept) values
('purchase_vat', 10, 'basic', 'purchase_invoice', 'VAT', 'Compra de mercaderías con IVA', 'Purchase of goods with VAT', 'Compras mercaderías a un proveedor por 2.000 € + IVA del 21 %, a pagar a 30 días.', 'You buy goods from a supplier for €2,000 + 21 % VAT, payable in 30 days.', '[{"account": "600", "side": "debit", "amount": 2000}, {"account": "472", "side": "debit", "amount": 420}, {"account": "400", "side": "credit", "amount": 2420}]'::jsonb, 'El IVA soportado es un derecho frente a Hacienda (472, al Debe). La deuda con el proveedor incluye el IVA.', 'Input VAT is a receivable from the tax agency (472, debit). The debt to the supplier includes the VAT.', '[{"account": "472", "side": "credit", "msg": "El IVA soportado va al Debe: es un derecho frente a Hacienda, no una deuda.", "msg_en": "Input VAT goes on the debit side: it is a receivable, not a debt."}, {"account": "410", "side": "credit", "msg": "Los proveedores de mercaderías van a la 400; la 410 es para acreedores por prestación de servicios.", "msg_en": "Suppliers of goods go to 400; 410 is for service creditors."}, {"account": "477", "side": "credit", "msg": "La 477 es el IVA repercutido (ventas); en una compra el IVA es soportado (472).", "msg_en": "477 is output VAT (sales); on a purchase VAT is input tax (472)."}]'::jsonb, '{liva,pgc}', 'inputTax'),
('sale_igic', 20, 'basic', 'sale_invoice', 'IGIC', 'Venta en Canarias con IGIC', 'Sale in the Canary Islands with IGIC', 'Una empresa de Tenerife vende mercaderías por 1.500 € + IGIC del 7 %.', 'A Tenerife company sells goods for €1,500 + 7 % IGIC.', '[{"account": "430", "side": "debit", "amount": 1605}, {"account": "700", "side": "credit", "amount": 1500}, {"account": "477", "side": "credit", "amount": 105}]'::jsonb, 'En Canarias no hay IVA: el impuesto es el IGIC, al 7 % el tipo general, y se repercute en la 477.', 'There is no VAT in the Canary Islands: the tax is IGIC, 7 % standard rate, recorded as output tax in 477.', '[{"account": "472", "side": "credit", "msg": "El impuesto que cobras al cliente es repercutido: la 477, no la 472.", "msg_en": "The tax you charge the customer is output tax: 477, not 472."}, {"account": "477", "side": "debit", "msg": "El IGIC repercutido es una deuda con la Hacienda canaria: va al Haber.", "msg_en": "Output IGIC is a debt to the Canary tax agency: credit side."}]'::jsonb, '{ley20_1991,pgc}', 'igic'),
('credit_memo_sale', 30, 'basic', 'credit_memo', 'VAT', 'Devolución de una venta', 'Sales return', 'Un cliente devuelve mercaderías: emites una factura rectificativa de 500 € + IVA del 21 %, que se descuenta de lo que te debe.', 'A customer returns goods: you issue a credit memo for €500 + 21 % VAT, deducted from what they owe you.', '[{"account": "708", "side": "debit", "amount": 500, "alt": ["700"]}, {"account": "477", "side": "debit", "amount": 105}, {"account": "430", "side": "credit", "amount": 605}]'::jsonb, 'La rectificativa hace lo contrario que la factura: la venta y el IVA bajan (al Debe) y el cliente debe menos (al Haber). El PGC tiene la 708 para las devoluciones de ventas.', 'The credit memo does the opposite of the invoice: sales and VAT go down (debit) and the customer owes less (credit). The PGC has account 708 for sales returns.', '[{"account": "430", "side": "debit", "msg": "El cliente debe MENOS: la 430 va al Haber.", "msg_en": "The customer owes LESS: 430 goes on the credit side."}, {"account": "477", "side": "credit", "msg": "Al devolver, el IVA repercutido baja: la 477 va al Debe.", "msg_en": "On a return, output VAT decreases: 477 goes on the debit side."}]'::jsonb, '{liva,pgc}', 'creditMemo'),
('professional_withholding', 40, 'medium', 'professional_invoice', 'VAT', 'Factura de una abogada con retención', 'Lawyer invoice with withholding', 'Recibes la factura de una abogada: honorarios de 1.000 € + IVA del 21 %, con una retención de IRPF del 15 %.', 'You receive a lawyers invoice: fees of €1,000 + 21 % VAT, with 15 % IRPF withholding.', '[{"account": "623", "side": "debit", "amount": 1000}, {"account": "472", "side": "debit", "amount": 210}, {"account": "4751", "side": "credit", "amount": 150}, {"account": "410", "side": "credit", "amount": 1060}]'::jsonb, 'La retención (15 % de la base) no se paga a la abogada: se ingresa en Hacienda con el modelo 111. A ella se le debe 1.000 + 210 − 150.', 'The withholding (15 % of the base) is not paid to the lawyer: it goes to the tax agency with form 111. She is owed 1,000 + 210 − 150.', '[{"account": "4751", "side": "debit", "msg": "La retención es una deuda con Hacienda (la ingresarás con el 111): al Haber.", "msg_en": "The withholding is a debt to the tax agency (paid with form 111): credit side."}, {"account": "473", "side": "debit", "msg": "La 473 es la retención que te hacen a ti (en tus ventas); la que practicas tú es la 4751.", "msg_en": "473 is the withholding applied to you (on your sales); the one you apply is 4751."}]'::jsonb, '{lirpf,rirpf,liva}', 'withholding'),
('partial_collection', 50, 'basic', 'collection', null, 'Cobro parcial de un cliente', 'Partial customer collection', 'Un cliente te paga por transferencia 1.000 € de una factura de 2.420 €.', 'A customer pays you €1,000 by bank transfer of a €2,420 invoice.', '[{"account": "572", "side": "debit", "amount": 1000}, {"account": "430", "side": "credit", "amount": 1000}]'::jsonb, 'Solo se cobra lo que entra en el banco; los 1.420 restantes siguen pendientes en la 430.', 'Only what reaches the bank is collected; the remaining 1,420 stay pending in 430.', '[{"account": "700", "side": "credit", "msg": "El cobro no es una venta nueva: la venta ya se registró con la factura.", "msg_en": "The collection is not a new sale: the sale was recorded with the invoice."}]'::jsonb, '{pgc}', 'openItem'),
('depreciation_year', 60, 'medium', 'depreciation', null, 'Amortización anual de una máquina', 'Annual depreciation of a machine', 'Una máquina comprada el 1 de enero por 12.000 € tiene una vida útil de 10 años y ningún valor residual. Asiento de amortización del año.', 'A machine bought on 1 January for €12,000 has a 10-year useful life and no residual value. Year-end depreciation entry.', '[{"account": "681", "side": "debit", "amount": 1200}, {"account": "281", "side": "credit", "amount": 1200}]'::jsonb, 'Amortización lineal: 12.000 / 10 = 1.200 al año. Va al gasto (681) y a la amortización acumulada (2813), que resta del activo sin tocar la 213.', 'Straight-line: 12,000 / 10 = 1,200 a year. It goes to expense (681) and accumulated depreciation (2813), which reduces the asset without touching 213.', '[{"account": "213", "side": "credit", "msg": "No se abona la cuenta del activo: la amortización acumulada (281) recoge lo amortizado.", "msg_en": "Do not credit the asset account: accumulated depreciation (281) records it."}]'::jsonb, '{pgc,lis}', 'depreciation'),
('bad_debt_allowance', 70, 'medium', 'bad_debt', null, 'Deterioro de un cliente moroso', 'Allowance for a doubtful customer', 'A 31 de diciembre un cliente debe 2.420 € vencidos hace 7 meses y se estima que no pagará la mitad.', 'At 31 December a customer owes €2,420, overdue for 7 months, and half is expected not to be paid.', '[{"account": "694", "side": "debit", "amount": 1210}, {"account": "490", "side": "credit", "amount": 1210}]'::jsonb, 'El deterioro (NRV 9.ª) es un gasto (694) y una corrección de valor del cliente (490); el cliente sigue debiendo los 2.420. Es deducible porque han pasado más de 6 meses (art. 13.1.a LIS).', 'The allowance (PGC rule 9) is an expense (694) and a valuation adjustment of the receivable (490); the customer still owes 2,420. It is deductible because more than 6 months have passed (art. 13.1.a LIS).', '[{"account": "430", "side": "credit", "msg": "No se da de baja al cliente: sigue debiendo. El deterioro va a la 490.", "msg_en": "Do not write off the customer: they still owe. The allowance goes to 490."}, {"account": "650", "side": "debit", "msg": "La 650 es para la insolvencia firme (pérdida definitiva); aquí es una estimación: 694.", "msg_en": "650 is for a definitive bad debt; this is an estimate: 694."}]'::jsonb, '{pgc,lis}', 'badDebt'),
('prepaid_insurance', 80, 'medium', 'accrual', null, 'Seguro pagado por adelantado', 'Prepaid insurance', 'El 1 de octubre se pagó la prima anual de un seguro, 1.200 €, y se llevó al gasto (625). Ajuste al 31 de diciembre.', 'On 1 October the annual insurance premium, €1,200, was paid and expensed (625). Adjustment at 31 December.', '[{"account": "480", "side": "debit", "amount": 900}, {"account": "625", "side": "credit", "amount": 900}]'::jsonb, 'De la prima, 3 meses son de este año (300) y 9 del siguiente (900). Esos 900 se sacan del gasto y quedan como gasto anticipado (480) hasta el año que viene (principio de devengo).', 'Of the premium, 3 months belong to this year (300) and 9 to the next (900). Those 900 are removed from expense and kept as a prepaid expense (480) until next year (accrual principle).', '[{"account": "485", "side": "debit", "msg": "La 485 es para ingresos anticipados; un gasto anticipado va a la 480.", "msg_en": "485 is for deferred income; a prepaid expense goes to 480."}]'::jsonb, '{pgc}', 'deferral'),
('lawsuit_provision', 90, 'advanced', 'provision', null, 'Provisión por un litigio', 'Provision for a lawsuit', 'A 31 de diciembre el abogado considera probable perder un juicio con una condena de 12.000 €, que se resolverá dentro de dos años.', 'At 31 December the lawyer considers it probable to lose a lawsuit with a €12,000 award, to be resolved in two years.', '[{"account": "678", "side": "debit", "amount": 12000}, {"account": "142", "side": "credit", "amount": 12000}]'::jsonb, 'Obligación probable de importe estimado (NRV 15.ª): se dota la provisión. A más de un año, a largo plazo (142); cuando falte menos de un año se pasará a la 5293.', 'Probable obligation with an estimated amount (PGC rule 15): a provision is recognised. Over one year, long term (142); when less than a year remains it moves to 5293.', '[{"account": "5293", "side": "credit", "msg": "Se resolverá dentro de dos años: es a largo plazo (142).", "msg_en": "It will be resolved in two years: it is long term (142)."}, {"account": "410", "side": "credit", "msg": "Todavía no hay una deuda cierta: es una provisión (142).", "msg_en": "There is no certain debt yet: it is a provision (142)."}]'::jsonb, '{pgc,lis}', 'provision'),
('inventory_change', 100, 'medium', 'inventory', null, 'Variación de existencias', 'Inventory change', 'Las existencias iniciales de mercaderías eran de 8.000 € y el recuento del 31 de diciembre da 6.000 €. Regularización.', 'Opening stock of goods was €8,000 and the 31 December count gives €6,000. Year-end adjustment.', '[{"account": "610", "side": "debit", "amount": 8000}, {"account": "300", "side": "credit", "amount": 8000}, {"account": "300", "side": "debit", "amount": 6000}, {"account": "610", "side": "credit", "amount": 6000}]'::jsonb, 'Se da de baja la existencia inicial (610 D / 300 H) y de alta la final (300 D / 610 H). La 610 queda con 2.000 deudores: lo consumido de más sobre lo comprado.', 'Remove the opening stock (610 Dr / 300 Cr) and record the closing stock (300 Dr / 610 Cr). 610 ends with a 2,000 debit: consumption above purchases.', '[{"account": "600", "side": "credit", "msg": "Las compras (600) no se tocan: la variación va a la 610.", "msg_en": "Purchases (600) are not touched: the change goes to 610."}]'::jsonb, '{pgc}', 'inventoryChange'),
('monthly_payroll', 110, 'medium', 'payroll', null, 'Nómina del mes', 'Monthly payroll', 'Nómina: sueldo bruto 2.000 €, cuota del trabajador a la Seguridad Social 130 €, cuota de la empresa 640 € y retención de IRPF 240 €. El líquido se pagará a fin de mes.', 'Payroll: gross salary €2,000, employee Social Security contribution €130, employer contribution €640 and IRPF withholding €240. Net pay will be paid at month end.', '[{"account": "640", "side": "debit", "amount": 2000}, {"account": "642", "side": "debit", "amount": 640}, {"account": "476", "side": "credit", "amount": 770}, {"account": "4751", "side": "credit", "amount": 240}, {"account": "465", "side": "credit", "amount": 1630}]'::jsonb, 'El bruto y la cuota de la empresa son gasto (640 y 642). A la Seguridad Social se le deben las dos cuotas (130 + 640), a Hacienda el IRPF y al trabajador el líquido: 2.000 − 130 − 240.', 'Gross pay and the employer contribution are expenses (640 and 642). Social Security is owed both contributions (130 + 640), the tax agency the IRPF and the employee the net pay: 2,000 − 130 − 240.', '[{"account": "572", "side": "credit", "msg": "El líquido aún no se ha pagado: se debe al trabajador (465). El pago será otro asiento.", "msg_en": "Net pay has not been paid yet: it is owed to the employee (465). Payment is another entry."}, {"account": "476", "side": "debit", "msg": "La Seguridad Social es una deuda (se paga el mes siguiente): la 476 va al Haber.", "msg_en": "Social Security is a debt (paid the following month): 476 goes on the credit side."}]'::jsonb, '{lgss,cotizacion2026,rirpf}', 'payroll'),
('vat_settlement', 120, 'basic', 'tax_settlement', 'VAT', 'Liquidación trimestral del IVA', 'Quarterly VAT settlement', 'Al final del trimestre el IVA repercutido suma 2.982 € y el soportado deducible 2.793 €. Asiento de liquidación.', 'At quarter end output VAT totals €2,982 and deductible input VAT €2,793. Settlement entry.', '[{"account": "477", "side": "debit", "amount": 2982}, {"account": "472", "side": "credit", "amount": 2793}, {"account": "4750", "side": "credit", "amount": 189}]'::jsonb, 'Se cancelan las dos cuentas (477 al Debe, 472 al Haber) y la diferencia es lo que se debe a Hacienda (4750) y se ingresa con el 303.', 'Both accounts are cleared (477 debit, 472 credit) and the difference is owed to the tax agency (4750), paid with form 303.', '[{"account": "4700", "side": "debit", "msg": "Repercutido mayor que soportado: sale a ingresar (4750), no a devolver (4700).", "msg_en": "Output above input: tax payable (4750), not receivable (4700)."}]'::jsonb, '{aeat303,liva}', 'settlement'),
('intra_eu_purchase', 130, 'advanced', 'intra_eu_acquisition', 'VAT', 'Compra a un proveedor alemán', 'Purchase from a German supplier', 'Compras mercaderías a un proveedor de Alemania (adquisición intracomunitaria) por 2.000 €; su factura no lleva IVA.', 'You buy goods from a German supplier (intra-EU acquisition) for €2,000; their invoice has no VAT.', '[{"account": "600", "side": "debit", "amount": 2000}, {"account": "472", "side": "debit", "amount": 420}, {"account": "477", "side": "credit", "amount": 420}, {"account": "400", "side": "credit", "amount": 2000}]'::jsonb, 'El comprador se repercute a sí mismo el IVA español (477) y lo deduce a la vez (472): el efecto es cero, pero las dos cuotas van al 303 (casillas 10/11 y 36/37). Al proveedor solo se le deben los 2.000.', 'The buyer self-assesses Spanish VAT (477) and deducts it at the same time (472): the net effect is zero, but both amounts go to form 303 (boxes 10/11 and 36/37). The supplier is owed only 2,000.', '[{"account": "400", "side": "credit", "msg": "Al proveedor alemán no se le paga IVA: la 400 es 2.000, sin los 420.", "msg_en": "No VAT is paid to the German supplier: 400 is 2,000, without the 420."}]'::jsonb, '{liva,aeat303}', 'reverseCharge'),
('year_end_result', 140, 'advanced', 'year_closing', null, 'Regularización del resultado', 'Closing the result', 'Al cierre del ejercicio los gastos (grupo 6) suman 50.000 € y los ingresos (grupo 7) 65.000 €. Asiento de regularización.', 'At year end expenses (group 6) total €50,000 and income (group 7) €65,000. Closing entry for the result.', '[{"account": "7", "side": "debit", "amount": 65000}, {"account": "6", "side": "credit", "amount": 50000}, {"account": "129", "side": "credit", "amount": 15000}]'::jsonb, 'Se dejan a cero las cuentas de gastos e ingresos contra la 129. Ingresos mayores que gastos: beneficio de 15.000, al Haber de la 129.', 'Expense and income accounts are closed to 129. Income above expenses: a 15,000 profit, credited to 129.', '[{"account": "129", "side": "debit", "msg": "Hay beneficio (65.000 > 50.000): la 129 queda al Haber.", "msg_en": "There is a profit (65,000 > 50,000): 129 is credited."}, {"account": "120", "side": "credit", "msg": "El resultado del año va a la 129; a la 120 (remanente) solo llega cuando se reparte.", "msg_en": "The years result goes to 129; it reaches 120 (retained earnings) only when distributed."}]'::jsonb, '{pgc}', 'closing')
on conflict (key) do update set sort = excluded.sort, level = excluded.level, operation = excluded.operation, tax_type = excluded.tax_type,
  title = excluded.title, title_en = excluded.title_en, statement = excluded.statement, statement_en = excluded.statement_en,
  expected = excluded.expected, explanation = excluded.explanation, explanation_en = excluded.explanation_en,
  errors = excluded.errors, sources = excluded.sources, concept = excluded.concept;

-- Intentos: los de cada usuario y los de la IA (by = 'ai': el asiento que propuso el Tutor para el enunciado)
create table if not exists erp.exercise_attempts (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users(id) on delete cascade,
  exercise    text not null references erp.exercises(key) on delete cascade,
  by          text not null default 'user' check (by in ('user', 'ai')),
  answer      jsonb not null,
  score       int not null,
  ok          boolean not null,
  created_at  timestamptz not null default now()
);
create index if not exists exercise_attempts_user_idx on erp.exercise_attempts (user_id, exercise);
create index if not exists exercise_attempts_exercise_idx on erp.exercise_attempts (exercise);
create index if not exists exercises_operation_idx on erp.exercises (operation);
create index if not exists exercises_concept_idx on erp.exercises (concept);
create index if not exists operations_concept_idx on erp.operations (concept);

alter table erp.operations enable row level security;
alter table erp.exercises enable row level security;
alter table erp.exercise_attempts enable row level security;
drop policy if exists read on erp.operations;
drop policy if exists read on erp.exercises;
drop policy if exists own on erp.exercise_attempts;
create policy read on erp.operations for select to authenticated using (true);
create policy read on erp.exercises for select to authenticated using (true);
create policy own on erp.exercise_attempts for select to authenticated using (user_id = auth.uid());
revoke all on erp.operations, erp.exercises, erp.exercise_attempts from anon, public;
grant select on erp.operations, erp.exercises, erp.exercise_attempts to authenticated;

-- ---------------------------------------------------------------------
-- 4) ¿A qué operación se parece un asiento? (para que el Tutor diga dónde se registra)
--   p_lines: [{ account_no, debit, credit }] → la operación que tiene TODAS sus cuentas en el asiento (la más concreta)
-- ---------------------------------------------------------------------
create or replace function erp.operation_for_lines(p_lines jsonb)
returns setof erp.operations language sql stable as $$
  select o.* from erp.operations o
  where not exists (
    select 1 from unnest(o.accounts) a
    where not exists (select 1 from jsonb_array_elements(p_lines) l where coalesce(l->>'account_no', '') like a || '%'))
  order by cardinality(o.accounts) desc, (select sum(length(a)) from unnest(o.accounts) a) desc, o.sort
  limit 1;
$$;

-- ---------------------------------------------------------------------
-- 5) Corregir una respuesta
--   p_answer: [{ account_no, debit, credit }] (la cuenta, de 3 o más dígitos: 600, 60000001…)
--   Cada línea esperada se busca por su grupo o subgrupo (o sus alternativas) y su lado:
--     ok      está y el importe coincide          amount  está pero el importe no
--     side    está, pero en el otro lado           missing no está
--   Las líneas de la respuesta que no casan con ninguna esperada son «extra». Los errores frecuentes que se reconocen
--   se explican. Puntuación: % de líneas esperadas bien; correcto si todas están bien, no hay extras y cuadra.
-- ---------------------------------------------------------------------
create or replace function erp.grade_exercise(p_key text, p_answer jsonb)
returns jsonb language plpgsql stable as $$
declare
  x erp.exercises; a jsonb; e jsonb; v_lines jsonb := '[]'; v_ok int := 0; v_n int := 0; v_match numeric; v_other numeric;
  v_used int[] := '{}'; v_extra jsonb := '[]'; v_tips jsonb := '[]'; v_status text; v_debit numeric; v_credit numeric; i int;
  v_alts text[]; v_hits int[];
begin
  select * into x from erp.exercises where key = p_key;
  if not found then raise exception 'Exercise % not found', p_key; end if;
  -- la respuesta, normalizada: [{ i, account, side, amount }]
  select coalesce(jsonb_agg(jsonb_build_object('i', o.ord, 'account', btrim(o.v->>'account_no'),
           'side', case when coalesce((o.v->>'debit')::numeric, 0) <> 0 then 'debit' else 'credit' end,
           'amount', abs(coalesce(nullif((o.v->>'debit')::numeric, 0), (o.v->>'credit')::numeric, 0))) order by o.ord), '[]'),
         coalesce(sum(coalesce((o.v->>'debit')::numeric, 0)), 0), coalesce(sum(coalesce((o.v->>'credit')::numeric, 0)), 0)
    into a, v_debit, v_credit
  from jsonb_array_elements(p_answer) with ordinality o(v, ord)
  where coalesce(btrim(o.v->>'account_no'), '') <> '' and (coalesce((o.v->>'debit')::numeric, 0) <> 0 or coalesce((o.v->>'credit')::numeric, 0) <> 0);

  for e in select * from jsonb_array_elements(x.expected) loop
    v_n := v_n + 1;
    v_alts := array[e->>'account'] || coalesce((select array_agg(z) from jsonb_array_elements_text(e->'alt') z), '{}');
    -- líneas de la respuesta de ese grupo y ese lado (que no haya usado otra línea esperada)
    select coalesce(sum((l->>'amount')::numeric), 0), coalesce(array_agg((l->>'i')::int), '{}') into v_match, v_hits
    from jsonb_array_elements(a) l
    where l->>'side' = e->>'side' and exists (select 1 from unnest(v_alts) p where l->>'account' like p || '%')
      and not ((l->>'i')::int = any (v_used));
    select coalesce(sum((l->>'amount')::numeric), 0) into v_other
    from jsonb_array_elements(a) l
    where l->>'side' <> e->>'side' and exists (select 1 from unnest(v_alts) p where l->>'account' like p || '%');
    v_status := case when cardinality(v_hits) > 0 and abs(v_match - (e->>'amount')::numeric) < 0.005 then 'ok'
                     when cardinality(v_hits) > 0 then 'amount'
                     when v_other <> 0 then 'side'
                     else 'missing' end;
    if v_status = 'ok' then v_ok := v_ok + 1; end if;
    v_used := v_used || v_hits;
    v_lines := v_lines || jsonb_build_object('account', e->>'account', 'side', e->>'side', 'expected', (e->>'amount')::numeric,
                                             'answered', case when cardinality(v_hits) > 0 then v_match end, 'status', v_status,
                                             'alt_used', cardinality(v_hits) > 0 and not exists (
                                               select 1 from jsonb_array_elements(a) l where (l->>'i')::int = any (v_hits) and l->>'account' like (e->>'account') || '%'));
  end loop;
  select coalesce(jsonb_agg(l - 'i'), '[]') into v_extra from jsonb_array_elements(a) l where not ((l->>'i')::int = any (v_used));
  -- errores frecuentes reconocidos
  select coalesce(jsonb_agg(jsonb_build_object('msg', r->>'msg', 'msg_en', r->>'msg_en')), '[]') into v_tips
  from jsonb_array_elements(x.errors) r
  where exists (select 1 from jsonb_array_elements(a) l where l->>'side' = r->>'side' and l->>'account' like (r->>'account') || '%');
  return jsonb_build_object('exercise', x.key, 'lines', v_lines, 'extra', v_extra, 'tips', v_tips,
    'balanced', abs(v_debit - v_credit) < 0.005, 'debit', v_debit, 'credit', v_credit,
    'score', case when v_n = 0 then 0 else round(100.0 * v_ok / v_n)::int end,
    'ok', v_ok = v_n and jsonb_array_length(v_extra) = 0 and abs(v_debit - v_credit) < 0.005);
end $$;

-- Corregir y guardar el intento
create or replace function erp.submit_exercise(p_key text, p_answer jsonb, p_by text default 'user')
returns jsonb language plpgsql security definer set search_path = erp, public as $$
declare g jsonb;
begin
  if auth.uid() is null then raise exception 'Sign in to practise'; end if;
  if p_by not in ('user', 'ai') then raise exception 'Invalid attempt: %', p_by; end if;
  g := erp.grade_exercise(p_key, p_answer);
  insert into erp.exercise_attempts (user_id, exercise, by, answer, score, ok)
  values (auth.uid(), p_key, p_by, p_answer, (g->>'score')::int, (g->>'ok')::boolean);
  return g;
end $$;

-- Progreso de cada usuario: por supuesto, intentos, mejor nota, si lo ha resuelto y lo que sacó la IA la última vez
create or replace view erp.v_exercise_progress with (security_invoker = true) as
select x.key, x.sort, x.level, x.operation, x.tax_type, x.title, x.title_en,
       count(t.id) filter (where t.by = 'user') as attempts,
       coalesce(max(t.score) filter (where t.by = 'user'), 0) as best_score,
       coalesce(bool_or(t.ok) filter (where t.by = 'user'), false) as solved,
       max(t.created_at) filter (where t.by = 'user') as last_at,
       (select a.score from erp.exercise_attempts a where a.exercise = x.key and a.by = 'ai' and a.user_id = auth.uid()
        order by a.created_at desc limit 1) as ai_score,
       (select a.ok from erp.exercise_attempts a where a.exercise = x.key and a.by = 'ai' and a.user_id = auth.uid()
        order by a.created_at desc limit 1) as ai_ok
from erp.exercises x
left join erp.exercise_attempts t on t.exercise = x.key and t.user_id = auth.uid()
group by x.key;
revoke all on erp.v_exercise_progress from anon, public;
grant select on erp.v_exercise_progress to authenticated;

revoke execute on function erp.operation_for_lines(jsonb), erp.grade_exercise(text, jsonb), erp.submit_exercise(text, jsonb, text) from anon, public;
grant execute on function erp.operation_for_lines(jsonb), erp.grade_exercise(text, jsonb), erp.submit_exercise(text, jsonb, text) to authenticated;
